package com.example.discovery.provider.api;import com.example.discovery.provider.config.ProviderProperties;import com.example.discovery.provider.model.PaymentResponse;import org.slf4j.*;import org.springframework.web.bind.annotation.*;@RestController public class PaymentController{private static final Logger log=LoggerFactory.getLogger(PaymentController.class);private final ProviderProperties p;public PaymentController(ProviderProperties p){this.p=p;} @GetMapping("/payments") public PaymentResponse payments(){log.info("[PROVIDER] Processing request on instance: {}",p.instanceId());return new PaymentResponse(p.serviceName(),p.instanceId(),p.port(),"Response from "+p.serviceName()+" instance "+p.port());}}
